"""Generate packages/contracts/billing.schema.json and billing.ts from the models of the plans and billing API (job DI, ADR 0092). Same scheme as the other contracts (`make contracts`; a test fails if either file
is stale). Committed early: the Plan screens are built against it."""

from __future__ import annotations

import json
from typing import Any

from pydantic import BaseModel
from pydantic.json_schema import models_json_schema

from app.billing import models as m
from app.packs.contracts import _ts_type

HEADER = (
    "// GENERATED by `make contracts` from services/ai-api/app/billing/models.py. Do not edit.\n"
    "// Plans, usage as counts and percentages, one notice at 80 and one at 100. AI is included under fair use: its rupees and tokens are never in these shapes.\n"
)
RESPONSES: list[type[BaseModel]] = [m.PlansOut, m.BillingOut, m.UsageViewOut]
REQUESTS: list[type[BaseModel]] = [m.TrialStartIn]


def build_schema() -> dict[str, Any]:
    _, defs = models_json_schema(
        [(model, "serialization") for model in RESPONSES] + [(model, "validation") for model in REQUESTS], ref_template="#/$defs/{model}"
    )
    return {
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "$id": "billing.schema.json",
        "title": "Plans and billing: the catalogue, usage meters, the trial (job DI)",
        "description": "Generated from services/ai-api/app/billing/models.py by `make contracts`.",
        "$defs": dict(sorted(defs.get("$defs", {}).items())),
    }


def schema_text() -> str:
    return json.dumps(build_schema(), indent=2, sort_keys=False) + "\n"


def ts_text() -> str:
    defs = build_schema()["$defs"]
    lines = [HEADER]
    for name, node in defs.items():
        ts_name = name.replace("_", "")
        if "enum" in node:
            lines.append(f"export type {ts_name} = {_ts_type(node)};\n")
            continue
        props = node.get("properties", {})
        required = set(node.get("required", []))
        body = []
        for prop, spec in props.items():
            optional = "" if prop in required else "?"
            body.append(f"  {prop}{optional}: {_ts_type(spec)};")
        lines.append(f"export interface {ts_name} {{\n" + "\n".join(body) + "\n}\n")
    return "\n".join(lines)
